package com.greatwy.hisenseenglishquiz;
import android.app.Activity; import android.os.Bundle; import android.graphics.Color; import android.graphics.Typeface; import android.view.Gravity; import android.view.View; import android.view.KeyEvent; import android.widget.LinearLayout; import android.widget.TextView; import android.widget.Button; import android.content.Intent; import java.util.Random;
public class QuizActivity extends Activity {
 int q=0,score=0; TextView title,progress,feedback; Button[] btns=new Button[4]; Word word;
 static class Word { String en; String[] o; Word(String e,String a,String b,String c,String d){en=e;o=new String[]{a,b,c,d};} }
 Word[] words={new Word("Apple","苹果","香蕉","橘子","葡萄"),new Word("Book","书","桌子","椅子","门"),new Word("Cat","猫","狗","鸟","鱼"),new Word("Water","水","火","米饭","牛奶"),new Word("Thank you","谢谢","对不起","你好","再见"),new Word("House","房子","学校","医院","商店"),new Word("Dog","狗","猫","马","兔子"),new Word("Red","红色","蓝色","绿色","黄色"),new Word("Good morning","早上好","晚安","再见","谢谢"),new Word("School","学校","公园","车站","厨房"),new Word("Family","家庭","朋友","老师","学生"),new Word("Milk","牛奶","果汁","水","茶"),new Word("Friend","朋友","医生","司机","警察"),new Word("Sun","太阳","月亮","星星","云"),new Word("Happy","快乐的","伤心的","疲倦的","生气的"),new Word("Goodbye","再见","你好","谢谢","早上好"),new Word("Big","大的","小的","高的","短的"),new Word("Small","小的","大的","新的","旧的"),new Word("Pen","钢笔","书","桌子","椅子"),new Word("Car","汽车","火车","飞机","自行车"),new Word("Mother","妈妈","爸爸","姐姐","弟弟"),new Word("Father","爸爸","妈妈","老师","朋友"),new Word("One","一","二","三","四"),new Word("Two","二","一","三","五"),new Word("Hello","你好","再见","谢谢","对不起")};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(4|2|4096);startService(new Intent(this,QuizTimerService.class));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setPadding(30,15,30,15);root.setBackgroundColor(Color.rgb(18,45,82));title=label("英语闯关",36,Color.WHITE,true);progress=label("",22,Color.WHITE,false);feedback=label("请选择正确的中文意思",22,Color.YELLOW,false);root.addView(title);root.addView(progress);root.addView(feedback);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER);for(int i=0;i<4;i++){final int x=i;btns[i]=new Button(this);btns[i].setTextSize(22);btns[i].setOnClickListener(v->answer(x));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,110,1);lp.setMargins(6,15,6,15);row.addView(btns[i],lp);}root.addView(row);setContentView(root);next();btns[0].requestFocus();}
 TextView label(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(8,10,8,10);return t;}
 void next(){if(q>=5){title.setText("全部答对！");feedback.setText("即将继续使用电视");for(Button b:btns)b.setVisibility(View.GONE);getWindow().getDecorView().postDelayed(()->{getSharedPreferences("quiz",0).edit().putLong("next_due",System.currentTimeMillis()+900000L).apply();finish();},1500);return;}word=words[new Random().nextInt(words.length)];title.setText("第 "+(q+1)+" 题："+word.en);progress.setText("答对 "+score+" / 5");feedback.setText("请选择正确的中文意思");String[] a=word.o.clone();Random r=new Random();for(int i=3;i>0;i--){int j=r.nextInt(i+1);String t=a[i];a[i]=a[j];a[j]=t;}for(int i=0;i<4;i++){btns[i].setVisibility(View.VISIBLE);btns[i].setText(a[i]);btns[i].setTag(a[i].equals(word.o[0]));}}
 void answer(int i){if(Boolean.TRUE.equals(btns[i].getTag())){q++;score++;feedback.setText("回答正确！");next();}else feedback.setText("回答错误，请再试一次");progress.setText("答对 "+score+" / 5");}
 @Override public void onBackPressed(){feedback.setText("请先答对 5 道题");}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getKeyCode()==KeyEvent.KEYCODE_BACK&&e.getAction()==KeyEvent.ACTION_UP){feedback.setText("请先答对 5 道题");return true;}return super.dispatchKeyEvent(e);}
}
